"""Curated runtime and test evidence; private captures remain local."""
from pathlib import Path
import hashlib,json,re
from datetime import datetime,timezone
here=Path(__file__).resolve().parent;root=here.parents[1]
def read(p):return json.loads((root/p).read_text(encoding='utf-8-sig'))
def save(p,v):(root/p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
def keep(v,names):return{k:v[k]for k in names if k in v}
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
dep=read('work/nss46/deployment-latest.json');cfg=read(dep['localDir']+'/config.json');assert dep['committed']
changes=[]
for kind,variable in [('backend-retain','reuse verified initial recovery reads'),('expiry-retain','typed expired software observation recovery'),('row-retain','typed 2048-row observation overload')]:
    d=read('work/nss46/'+kind+'/deployment-latest.json');cp=read(d['localDir']+'/checkpoint.json');arm=read(d['localDir']+'/armed-proof.json');audit=read(d['localDir']+'/permanent-before-commit-audit.json');commit=read(d['localDir']+'/permanent-commit.json')
    assert cp['gzipVerified']and arm['passed']and arm['independentOfSsh']and audit['passed']and commit['committed']
    changes.append({'phase':kind,'oneMajorVariable':variable,'committed':True,'checkpointDownloadedHashAndGzipVerified':True,'independentRollbackVerifiedBeforeWrite':True,'independentRollbackSeconds':180,'stageExpirySeconds':480,'protectedConfigurationAuditPassed':True,'configSha256':d['configHash'],'nssEnabled':False})
