timing=[]
for name,d in [('source-expiry',fault),('worker-crash',crash)]:
    cp=read(d['localDir']+'/checkpoint.json');arm=read(d['localDir']+'/armed-proof.json');undo=read(d['localDir']+'/rollback-qualified.json');assert cp['gzipVerified']and arm['passed']and undo['passed']and undo['automaticExpiryWithoutControllerRollback']
    timing.append({'test':name,'checkpointDownloadedHashAndGzipVerified':True,'independentRollbackVerifiedBeforeWrite':True,'independentRollbackSeconds':180,'automaticNaturalTransactionRollbackPassed':True,'allFourSourcesConfigAndPointerRestored':True,'ecmClosedAndZero':True})
log=(here/'fault-child-log-private.txt').read_text();m=re.search(r'action=recover rawStatus=0 elapsed=([\d.]+)',log);assert m
faultq['actualRecoveryChildSeconds']=float(m[1]);faultq['realConnectionMetadataUnmodified']=True;faultq['bothPublicationsWithdrawnBeforeRecovery']=True;faultq['pendingIntentsBeforeRecovery']=max(r['intents']for r in faultobs['rows']if r['status']=='degraded');faultq['recoveredIntents']=0
align=read('work/nss46/entry-prewrite-alignment-private.json');entry=read('work/nss46/entry-qualified.json');assert entry['passed']and not entry['seedOnly'];final=read('work/nss46/final-audit.json');closure=read('work/nss46/final-closure.json');inspect=read('work/nss46/classifier-final-inspection.json');pc=read('work/nss46/real-reader-qualified.json')
assert final['passed']and closure['passed']
obs=read('work/nss46/retained-observation-qualified.json');raw=read('work/nss46/retained-observation-private.json');a,b=raw['rows'][0],raw['rows'][-1]
def cpu(s):return [int(v)for v in s.split()[1:]]
x,y=cpu(a['cpu']),cpu(b['cpu']);diff=[p-q for p,q in zip(y,x)];total=sum(diff[:8]);obs['cpuBusyPercent']=(1-(diff[3]+diff[4])/total)*100;obs['softirqPercent']=diff[6]/total*100
def soft(s,col):return sum(int(row.split()[col],16)for row in s.splitlines())
obs['timeSqueezeDelta']=soft(b['softnet'],2)-soft(a['softnet'],2);obs['softnetDroppedDelta']=soft(b['softnet'],1)-soft(a['softnet'],1)
# Freeze this round only; never modify the previous rounds' proof folders.
sources=sorted(p for p in here.iterdir()if p.is_file()and p.suffix in ['.py','.mjs','.lua'])
frozen=here/'source-frozen';frozen.mkdir()
hashes={}
for p in sources:(frozen/p.name).write_bytes(p.read_bytes());hashes[p.relative_to(root).as_posix()]=sha(p)
save('work/nss46/source-proof-private.json',{'passed':True,'sourceHashes':hashes,'sources':len(hashes)})
out={'round':'NSS46','observedAt':datetime.now(timezone.utc).isoformat(),'deploymentReference':'work/nss46/deployment-latest.json','classifierConfigSha256':dep['configHash'],'classifierCommitted':True,'permanentClassifierChanged':True,'routerConfigurationWrites':True,'nssOpened':False,'originalNss42EntryUnmodified':True,'budgetMbps':20,'gateFlows':{'tcp':1,'udp':1},'ownerDeadlineSeconds':45,'softwareSourceAgeSeconds':6,'publicationAgeSeconds':9,'sourceRowsLimit':2048,'sourceBytesLimit':524288,'retainedChanges':changes,'realSoftwareExpiry':faultq,'realWorkerCrash':crashq,'independentFaultTrialRollbacks':timing,'entry':{'passed':True,'boundInputs':len(entry['sourceManifest']),'localCases':sum(read('work/nss46/'+name)['checks']for name in ['parser-qualified.json','controller-qualified.json','dependency-qualified.json','binding-qualified.json','entry-scheduling-qualified.json']),'classificationHintSourceAgeSeconds':align['alignment']['sourceAge'],'fullLockedAudit':keep(read('work/nss46/entry-prewrite-audit.json'),['passed','protectedConfigurationUnchanged','exactOwnedNativeAudit','queryAge','ecmClosedAndZero']),'nssLuaPayloadsByteIdenticalToQualifiedNss39':True,'actualNssTrafficTestThisRound':False,'initialAndNativeDeadlinesUnchanged':True},'retainedNaturalObservation':obs,'localRegression':{'rowCases':48,'combinedExpiryCases':34,'uniqueAssertionsInCombinedRegression':82,'priorNativeQueryCasesReused':7,'nativeQueryHelperBytesUnchanged':True,'notCountedAsNewNativeCases':True},'startupTransition':{'expiryRetentionFirstThreeRowsSawOldProducerOrNewGuardianWarmup':True,'latestNewInstanceAuditBeforeCommitPassed':True,'continuousHealthFromInstallerStartNotClaimed':True},'finalState':{'protectedAudit':keep(final,['passed','protectedConfigurationUnchanged','exactOwnedNativeAudit','ecmClosedAndZero']),'classifierHealthy':inspect['files']['guardian.json']['healthy'],'closure':keep(closure,['passed','observedAt','noActiveRootTransaction','noNssStagingDirectory','noExperimentStateNodeDirectory','noExperimentalGateOrQdiscModule']),'lastErrorIsControlledTrialPredeadlineExit':'Installation rollback deadline reached'in inspect['files']['last-error.json']['error'],'lastErrorBelongsToCurrentWorker':inspect['files']['last-error.json']['producer']==inspect['files']['classification.json']['producer'],'lastApplication':keep(pc,['observedAt','gameProcessRunning','steamProcessRunning','actualCs2RtCandidates','actualSteamBulkCandidates','sameWanCandidates'])},'sourceProof':{'sources':len(hashes),'sourceHashes':hashes,'newEntryQualified':True,'sourceFreezeAloneDoesNotQualifyNss':True},'conclusions':{'realApplyChildAndRecoveryPassed':True,'realLightLoadCrashRecoveryPassed':True,'newEntryBoundAndNativeAuditPassed':True,'newNssFastPathTrialExecuted':False,'nssCpuBenefitProvedThisRound':False,'cs2JitterLossMissCaptured':False,'classifierHighLoadStable':False,'completeHighLoadLoopPassed':False,'secondWanExpansionAllowed':False},'remainingRisks':['Real Steam+CS2 high-load recovery and matched load still untested','Live port-change and old-flow exit remain algorithmically tested; current round has no CS2','Controlled 20 Mbps subset can be too small for a useful whole-router CPU comparison','No client game telemetry or subjective comparison this round'],'upstreamSubmission':False,'reportVerification':{'sourceValidated':True,'browserRendered':False,'existingLocalFileBrowserPolicyRefusalRespected':True}}
save('outputs/nss46-mainline-observations.json',out)
rows=[{'atSeconds':round(r['at']-faultobs['rows'][0]['at'],4),**keep(r,['status','fullStatus','sequence','sourceAge','entries','intents','frontend','accelerated','stopped','degradation'])}for r in faultobs['rows']]
save('work/nss46/fault-timing-sanitized.json',{'testOnlyTimingFault':True,'flowEndpointsOmitted':True,'nssEnabled':False,'rows':rows})
save('work/nss46/entry-binding-sanitized.json',keep(entry,['round','qualificationVersion','configuration','nssRouterPayloadsUnchanged','classifierReliabilityChangesBound','auditPurposeSeparated','recoveryUsesOriginalFullAudit','prewriteSchedulingOnly','schedulingCannotAuthorizeNss','initialAndNativeDeadlinesUnchanged','initialAgeSeconds','prelearningAgeSeconds','ownerDeadlineSeconds','lockedAuditSourceAgeSeconds','lockedAuditPublicationAgeSeconds','alignmentInnerSeconds','alignmentOuterSeconds','flowCount','controlledBudgetMbps','nssHardwareQualifiedThisRound','seedOnly']))
print(json.dumps({'summarized':True,'newSourceFiles':len(hashes),'permanentClassifierChanged':True,'realChildAndCrashRecovery':True,'newEntryBoundInputs':len(entry['sourceManifest']),'nssOpened':False}))
